typedef unsigned char u_char;
typedef unsigned long long u_long128 __attribute__((mode(TI)));
#define NULL 0

struct sceMpeg {
    unsigned char data[0x48];
};
struct sceMpegCbData;
struct sceMpegCbDataError;
struct sceMpegCbDataTimeStamp;
typedef int (*sceMpegCallback)(sceMpeg*, sceMpegCbData*, void*);

enum {
    sceMpegCbError = 0,
    sceMpegCbNodata = 1,
    sceMpegCbStopDMA = 2,
    sceMpegCbRestartDMA = 3,
    sceMpegCbTimeStamp = 5
};

typedef struct
{
    long            pts;
    long            dts;
    int             pos;
    int             len;
} TimeStamp;

typedef struct
{
    u_long128       *data;
    u_long128       *tag;
    int             n;
    int             dmaStart;
    int             dmaN;
    int             readBytes;
    int             buffSize;
} ViBuf;

typedef struct
{
    sceMpeg         mpeg;
    ViBuf           vibuf;
    unsigned int    state;
    int             sema;
    int             hid_endimage;
    int             hid_vblank;
} VideoDec;

extern int sceMpegCreate(sceMpeg*, u_char*, int);
extern int sceMpegAddCallback(sceMpeg*, int, sceMpegCallback, void*);
static int mpegError(sceMpeg*, sceMpegCbDataError*, void*);
static int mpegNodata(sceMpeg*, sceMpegCbData*, void*);
static int mpegStopDMA(sceMpeg*, sceMpegCbData*, void*);
static int mpegRestartDMA(sceMpeg*, sceMpegCbData*, void*);
static int mpegTS(sceMpeg*, sceMpegCbDataTimeStamp*, void*);
static void videoDecReset(VideoDec*);
static int viBufCreate(ViBuf*, u_long128*, u_long128*, int, TimeStamp*, int);

static int videoDecCreate( VideoDec* vd, u_char* mpegWork, int mpegWorkSize, u_long128* data, u_long128* tag, int tagSize, TimeStamp* pts, int n_pts )
{
    sceMpegCreate( &vd->mpeg, mpegWork, mpegWorkSize );
    sceMpegAddCallback( &vd->mpeg, sceMpegCbError, (sceMpegCallback)mpegError, NULL );
    sceMpegAddCallback( &vd->mpeg, sceMpegCbNodata, mpegNodata, NULL );
    sceMpegAddCallback( &vd->mpeg, sceMpegCbStopDMA, mpegStopDMA, NULL );
    sceMpegAddCallback( &vd->mpeg, sceMpegCbRestartDMA, mpegRestartDMA, NULL );
    sceMpegAddCallback( &vd->mpeg, sceMpegCbTimeStamp, (sceMpegCallback)mpegTS, NULL );
    videoDecReset(vd);
    viBufCreate(&vd->vibuf, data, tag, tagSize, pts, n_pts);
    return 1;
}
